<?php require __DIR__.'/includes/db.php'; require __DIR__.'/includes/auth.php'; require_login(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=$pdo->prepare('INSERT INTO students(name,roll_number,email,course) VALUES(?,?,?,?)');$s->execute([trim($_POST['name']),trim($_POST['roll_number']),trim($_POST['email']),trim($_POST['course'])]);header('Location: student_detail.php?id='.$pdo->lastInsertId());exit;}catch(Throwable $e){$error='Could not save. Check required fields and ensure roll number/email are unique.';}} ?><!doctype html><meta charset="utf-8"><link rel="stylesheet" href="admin.css"><main class="main" style="margin:5vh auto;max-width:700px"><section class="table-card" style="padding:28px"><h1>Add student</h1><?php if($error)echo '<p>'.$error.'</p>';?><form method="post" class="edit-form"><label>Full name<input name="name" required></label><label>Roll number<input name="roll_number" required></label><label>Email<input type="email" name="email" required></label><label>Course<input name="course" required></label><button class="add-btn">Save student</button> <a href="view_students.php">Cancel</a></form></section></main><style>.edit-form label{display:block;margin:17px 0}.edit-form input{display:block;width:100%;padding:12px;border:1px solid #dce3ee;border-radius:7px;margin-top:7px}</style>
